const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const revenueProviders={wechat:'微信支付',alipay:'支付宝'};
export const revenueKinds={membership:'会员订阅',bundle:'专项套餐',credits:'积分充值',other:'其他商品'};
const ranges={today:'今天','7d':'最近 7 天','30d':'最近 30 天','90d':'最近 90 天',month:'本月',lastMonth:'上月',custom:'自定义日期'};
export const revenueMoney=value=>Number.isSafeInteger(value)&&value>=0?'¥'+Math.floor(value/100).toLocaleString('zh-CN')+'.'+String(value%100).padStart(2,'0'):'—';
const number=value=>Number.isSafeInteger(value)&&value>=0?value.toLocaleString('zh-CN'):'—';
const time=value=>Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)):'—';
export const newRevenueQuery=()=>({range:'30d',provider:'',kind:'',page:1,pageSize:20});
export function revenueQueryString(query,{exporting=false}={}){
 return new URLSearchParams({range:query.range,...(query.range==='custom'?{startDate:query.startDate||'',endDate:query.endDate||''}:{}),...(query.provider?{provider:query.provider}:{}),...(query.kind?{kind:query.kind}:{}),...(!exporting?{page:String(query.page||1),pageSize:String(query.pageSize||20)}:{})}).toString();
}
const validSummary=value=>value&&['amountCents','orders','buyers','averageCents'].every(key=>Number.isSafeInteger(value[key])&&value[key]>=0);
export function revenueDataValid(data){
 return data?.currency==='CNY'&&data.basis==='paid_orders'&&validSummary(data.summary)&&['today','month','allTime'].every(key=>validSummary(data.totals?.[key]))&&['daily','byProvider','byKind','products','items'].every(key=>Array.isArray(data[key]))&&data.filters?.timezone==='Asia/Shanghai'&&Number.isSafeInteger(data.total)&&Number.isSafeInteger(data.page)&&Number.isSafeInteger(data.pageSize);
}
export function revenueOverview(data){
 const totals=data?.totals;
 return `<section class="panel revenue-overview" data-revenue-overview><div class="panel-heading"><div><h2>收益概览</h2><p>已支付订单实收 · 北京时间</p></div><a class="text-button" href="#revenue" data-view="revenue">查看收益统计 →</a></div><div class="revenue-mini-grid">${[['今日实收','today'],['本月实收','month'],['累计实收','allTime']].map(([title,key])=>`<div><span>${title}</span><strong>${revenueMoney(totals?.[key]?.amountCents)}</strong><small>${totals?number(totals[key]?.orders)+' 笔支付订单':'等待服务端统计'}</small></div>`).join('')}</div></section>`;
}
function trend(daily){
 if(!daily.some(row=>row.amountCents>0))return '<div class="revenue-empty">这个期间暂无已支付收入</div>';
 const w=1000,h=235,left=90,right=22,top=18,bottom=37,plotW=w-left-right,plotH=h-top-bottom,max=Math.max(100,...daily.map(row=>row.amountCents)),bar=plotW/daily.length;
 const grid=Array.from({length:4},(_,i)=>{const y=top+plotH*i/3;return `<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/><text x="${left-10}" y="${y+4}" text-anchor="end">${revenueMoney(Math.round(max*(1-i/3)))}</text>`;}).join('');
 const bars=daily.map((row,i)=>{const height=row.amountCents/max*plotH,width=Math.min(24,Math.max(1,bar*.68)),x=left+(i+.5)*bar-width/2,y=top+plotH-height,label=row.date+' · '+revenueMoney(row.amountCents)+' · '+number(row.orders)+' 笔';return `<g role="button" tabindex="0" data-revenue-day="${esc(row.date)}" aria-label="查看 ${esc(label)}"><title>${esc(label)}</title><rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${width.toFixed(2)}" height="${height.toFixed(2)}" rx="${Math.min(4,bar/5)}"/><rect class="revenue-hit" x="${(left+i*bar).toFixed(2)}" y="${top}" width="${bar.toFixed(2)}" height="${plotH}"/></g>`;}).join('');
 const ticks=[...new Set([0,...Array.from({length:5},(_,i)=>Math.round((daily.length-1)*(i+1)/5))])];
 return `<div class="revenue-chart"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="每日实收收入，点击某日查看明细"><g class="revenue-chart-grid">${grid}</g><g class="revenue-bars">${bars}</g><g class="revenue-chart-labels">${ticks.map(i=>`<text x="${left+(i+.5)*bar}" y="${h-10}" text-anchor="middle">${esc(daily[i].date.slice(5).replace('-','/'))}</text>`).join('')}</g></svg></div>`;
}
function breakdown(rows,names,total,{provider=false}={}){
 return `<div class="revenue-breakdown">${rows.map(row=>{const share=total?Math.min(100,row.amountCents/total*100):0;return `<div class="revenue-breakdown-row"><div><span class="revenue-dot ${provider&&row.key==='wechat'?'wechat':provider?'alipay':esc(row.key)}"></span><b>${esc(names[row.key]||row.key)}</b><strong>${revenueMoney(row.amountCents)}</strong></div><div class="revenue-progress"><i style="width:${share.toFixed(2)}%"></i></div><small>${number(row.orders)} 笔订单 <span>${share.toFixed(1)}%</span></small></div>`;}).join('')}</div>`;
}
export function revenuePage(data){
 const f=data.filters,s=data.summary,previous=data.previous,summaryCards=[['期间实收',revenueMoney(s.amountCents),'仅计入确认支付成功的订单','primary'],['支付订单',number(s.orders),'本期间支付成功的订单数',''],['付费用户',number(s.buyers),'同一用户购买多次计为 1 人',''],['平均每单',revenueMoney(s.averageCents),'期间实收 ÷ 支付订单数','']];
 const compare=previous.amountCents>0?`${s.amountCents>=previous.amountCents?'增长':'减少'} ${Math.abs((s.amountCents-previous.amountCents)/previous.amountCents*100).toFixed(1)}%`:s.amountCents?'上期暂无收入':'与上期持平';
 const pages=Math.max(1,Math.ceil(data.total/data.pageSize));
 return `<div class="revenue-page" data-revenue-page>
  <form id="revenue-filter" class="panel revenue-filter"><div class="revenue-filter-fields"><label>统计期间<select name="range">${Object.entries(ranges).map(([key,title])=>`<option value="${key}" ${f.range===key?'selected':''}>${title}</option>`).join('')}</select></label><div class="revenue-custom" data-revenue-custom ${f.range==='custom'?'':'hidden'}><label>开始日期<input name="startDate" ${f.range==='custom'?'':'disabled'} type="date" min="2000-01-01" max="${esc(f.today)}" value="${esc(f.startDate)}"></label><label>结束日期<input name="endDate" ${f.range==='custom'?'':'disabled'} type="date" min="2000-01-01" max="${esc(f.today)}" value="${esc(f.endDate)}"></label></div><label>支付渠道<select name="provider"><option value="">全部渠道</option>${Object.entries(revenueProviders).map(([key,title])=>`<option value="${key}" ${f.provider===key?'selected':''}>${title}</option>`).join('')}</select></label><label>商品类型<select name="kind"><option value="">全部商品</option>${Object.entries(revenueKinds).map(([key,title])=>`<option value="${key}" ${f.kind===key?'selected':''}>${title}</option>`).join('')}</select></label><div class="revenue-filter-actions"><button class="button primary" type="submit">查询</button><button class="button" type="button" data-revenue-reset>重置</button></div></div><p>${esc(f.startDate)} 至 ${esc(f.endDate)} · 按北京时间的支付成功时间统计</p><span class="form-error" data-revenue-filter-error role="alert" hidden></span></form>
  ${data.dataQuality?.excludedPaidOrders?`<div class="revenue-data-note" role="status">全站有 ${number(data.dataQuality.excludedPaidOrders)} 笔已支付订单缺少有效金额、交易号或支付时间，未计入实收。<a href="#orders" data-revenue-check-orders>查看已支付订单 →</a></div>`:''}
  <div class="revenue-metrics">${summaryCards.map(([title,value,note,color])=>`<article class="revenue-metric ${color}"><span>${title}</span><strong>${value}</strong><p>${note}</p></article>`).join('')}</div>
  <section class="panel revenue-running"><span>截至 ${esc(time(data.asOf))} · 当前渠道与商品筛选</span><div>${[['今日实收','today'],['本月实收','month'],['累计实收','allTime']].map(([title,key])=>`<p>${title}<b>${revenueMoney(data.totals[key].amountCents)}</b></p>`).join('')}</div></section>
  <div class="revenue-top-grid"><section class="panel"><div class="panel-heading"><div><h2>收入趋势</h2><p>${esc(f.startDate)} — ${esc(f.endDate)} · 点击柱形可查看当天</p></div><span class="revenue-comparison">${esc(compare)}<small>对比 ${esc(previous.startDate)} — ${esc(previous.endDate)}</small></span></div>${trend(data.daily)}</section><section class="panel"><div class="panel-heading"><div><h2>收款渠道</h2><p>所选期间的实收分布</p></div></div>${breakdown(data.byProvider,revenueProviders,s.amountCents,{provider:true})}</section></div>
  <div class="revenue-bottom-grid"><section class="panel"><div class="panel-heading"><div><h2>商品销售</h2><p>按收入排序 · 展示前 10 项 · 保留订单商品名称</p></div></div>${data.products.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>商品</th><th>类型</th><th>支付订单</th><th>实收收入</th></tr></thead><tbody>${data.products.map(row=>`<tr><td class="revenue-product-title">${esc(row.title)}</td><td>${esc(revenueKinds[row.kind]||'其他商品')}</td><td>${number(row.orders)}</td><td class="cell-number">${revenueMoney(row.amountCents)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="revenue-empty">暂无商品销售记录</div>'}</section><section class="panel"><div class="panel-heading"><div><h2>收入构成</h2><p>会员、套餐与积分分别统计</p></div></div>${breakdown(data.byKind,revenueKinds,s.amountCents)}</section></div>
  <section class="panel revenue-orders"><div class="panel-heading"><div><h2>收入明细 <span class="revenue-count">${number(data.total)} 笔</span></h2><p>按支付时间从新到旧排列</p></div><button class="button" data-revenue-export ${data.total?'':'disabled'}>导出明细 CSV</button></div>${data.items.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>支付时间</th><th>商品</th><th>支付渠道</th><th>实收金额</th><th>用户</th><th>商户订单号</th><th>操作</th></tr></thead><tbody>${data.items.map(row=>`<tr><td>${esc(time(row.paidAt))}</td><td><div class="cell-title revenue-product-title">${esc(row.productTitle)}</div><small>${esc(revenueKinds[row.kind]||'其他商品')}</small></td><td>${esc(revenueProviders[row.provider]||row.provider)}</td><td class="cell-number">${revenueMoney(row.amountCents)}</td><td>${esc(row.userName||'未填写昵称')}</td><td><span class="cell-id" title="${esc(row.outTradeNo)}">${esc(row.outTradeNo)}</span></td><td><button class="text-button" data-revenue-order="${esc(row.id)}">查看订单</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="revenue-empty">所选期间和筛选条件下没有支付成功的订单</div>'}<div class="pagination"><span>每页 ${data.pageSize} 条 · 共 ${number(data.total)} 笔</span><div class="pagination-buttons"><button class="button compact" data-revenue-page="previous" ${data.page<=1?'disabled':''}>上一页</button><span>${data.page} / ${pages}</span><button class="button compact" data-revenue-page="next" ${data.page>=pages?'disabled':''}>下一页</button></div></div></section>
  <details class="panel revenue-basis"><summary>统计口径与收入范围</summary><p>以已确认支付成功的订单原始金额为准，按北京时间的支付日统计。商品改价或改名不重算历史订单。未支付、失败、关闭、已退款订单不计入；重复支付通知只对应一笔订单。</p><p>会员订阅、专项套餐和积分充值分别统计；积分消费、套餐使用、管理员赠送积分或会员不重复计作收入。本页为订单实收口径，不是扣除退款、支付手续费、税费与模型成本后的净利润；平台外操作和退款金额需结合支付平台账单核对。</p>${data.dataQuality?.markedRefundedOrders?`<p>全站 ${number(data.dataQuality.markedRefundedOrders)} 笔订单已标记退款，已排除在当前实收统计外。</p>`:''}<p>自定义期间最长 366 天；单次最多导出 ${number(data.exportLimit)} 笔明细，超出时缩小日期范围或筛选渠道。累计实收不受所选日期范围限制，但沿用当前渠道与商品筛选。</p></details>
 </div>`;
}
